import{_ as r,c as l,o,ae as a}from"./chunks/framework.CXj_Gucb.js";const i="/oe-user-guide/assets/app-centre-doc.CZ-tBRDH.png",e="/oe-user-guide/assets/doc-filter.CP4Pd-y0.png",s="/oe-user-guide/assets/doc-detail.D-B_lcI1.png",d="/oe-user-guide/assets/doc-info.BAc5dNdN.png",n="/oe-user-guide/assets/doc-tbd.CDG1NU3U.png",h="/oe-user-guide/assets/doc-add.BrTkXeMX.png",g="/oe-user-guide/assets/doc-action.Durf2bBa.png",P=JSON.parse('{"title":"文档AI预警类","description":"","frontmatter":{},"headers":[],"relativePath":"doc.md","filePath":"doc.md","lastUpdated":1766459798000}'),u={name:"doc.md"};function c(b,t,p,_,q,m){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="文档ai预警类" tabindex="-1">文档AI预警类 <a class="header-anchor" href="#文档ai预警类" aria-label="Permalink to &quot;文档AI预警类&quot;">​</a></h1><p><strong>版本：1.0</strong><br><strong>发布日期：2026年01月01日</strong><br><strong>适用对象：预警接收人、行动项责任人、片区质量/EHS代表、合规委员</strong></p><h2 id="一、角色说明" tabindex="-1">一、角色说明 <a class="header-anchor" href="#一、角色说明" aria-label="Permalink to &quot;一、角色说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>权限范围</th><th>操作入口</th></tr></thead><tbody><tr><td><strong>预警项/行动项接收人</strong></td><td>仅处理分配给自己的任务<br>• 无【应用中心】权限</td><td>首页 → 【待确认预警项】<br>首页 → 【待完成行动项】</td></tr><tr><td><strong>应用负责人</strong><br>（片区质量/EHS代表、合规委员）</td><td>可检索本片区全部预警<br>• 可导出、分析数据</td><td>【预警应用中心】→ 各子应用</td></tr></tbody></table><h2 id="二、操作指引" tabindex="-1">二、操作指引 <a class="header-anchor" href="#二、操作指引" aria-label="Permalink to &quot;二、操作指引&quot;">​</a></h2><h3 id="_2-1-功能概述" tabindex="-1">2.1 功能概述 <a class="header-anchor" href="#_2-1-功能概述" aria-label="Permalink to &quot;2.1 功能概述&quot;">​</a></h3><p>系统自动从业务系统获取文档样本（如巡检表、大部件、力矩报告等），AI 模型将识别以下风险：</p><ul><li>关键信息确实（如签名、盖章、日期缺失等）</li><li>检查结论不合格</li></ul><h3 id="_2-2-适用业务" tabindex="-1">2.2 适用业务 <a class="header-anchor" href="#_2-2-适用业务" aria-label="Permalink to &quot;2.2 适用业务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>业务域</th><th>应用名称</th></tr></thead><tbody><tr><td><strong>大现场质量</strong></td><td>现场文档 AI 检查</td></tr><tr><td><strong>大现场 EHS</strong></td><td>大现场 EHS 风险预警</td></tr></tbody></table><h3 id="_2-3-主界面" tabindex="-1">2.3 主界面 <a class="header-anchor" href="#_2-3-主界面" aria-label="Permalink to &quot;2.3 主界面&quot;">​</a></h3><p>进入路径：【预警应用中心】 → 【文档AI检测应用】</p><p><img src="'+i+'" alt="文档类主列表页"></p><h3 id="_2-4-筛选与查询" tabindex="-1">2.4 筛选与查询 <a class="header-anchor" href="#_2-4-筛选与查询" aria-label="Permalink to &quot;2.4 筛选与查询&quot;">​</a></h3><p>支持按以下条件筛选：</p><ul><li>预警项编号、时间、状态</li><li>AI 监测模型（如力矩报告、防火/巡检）</li><li>所属大区、工单号、项目编码等</li></ul><p><img src="'+e+'" alt="文档类筛选区"></p><h3 id="_2-5-预警详情与复核" tabindex="-1">2.5 预警详情与复核 <a class="header-anchor" href="#_2-5-预警详情与复核" aria-label="Permalink to &quot;2.5 预警详情与复核&quot;">​</a></h3><ul><li>点击右侧的【查看】按钮，进入详情页：</li></ul><p><img src="'+s+'" alt="文档详情页 - 全景视图"></p><ul><li>在详情页中： <ul><li>居中展示 <strong>文档 PDF</strong>，AI 自动高亮异常区域（如红色框标出“无签名”）</li><li>左侧显示 <strong>预警列表</strong>，列出具体问题点（如“No 1: 信息缺失”）</li><li>右侧展示 <strong>预警信息</strong> 与 <strong>文档基础数据</strong>（文件名、上传人、工单号等）</li></ul></li></ul><p><img src="'+d+'" alt="预警详情"></p><ul><li>在【确认信息】区域： <ul><li>选择 <strong>是否问题</strong>（是 / 否）</li><li>填写 <strong>确认描述</strong>（必填）</li></ul></li></ul><blockquote><p>✅ 当选择“是”时，需点击 <strong>【处理】</strong> 按钮，系统将弹出【预警处理】弹窗，提供以下三种处理方式：</p></blockquote><h4 id="处理方式一-等待处理" tabindex="-1">处理方式一：等待处理 <a class="header-anchor" href="#处理方式一-等待处理" aria-label="Permalink to &quot;处理方式一：等待处理&quot;">​</a></h4><ul><li><strong>适用场景</strong>：问题已识别，但暂不立即整改（如需协调资源、等待审批等）</li><li><strong>操作步骤</strong>： <ul><li>在弹窗中选择 <strong>“是”</strong></li><li>从下拉菜单选择 <strong>“等待处理”</strong></li><li>填写补充说明（如“待下周统一补签”）</li></ul></li></ul><p><img src="'+n+'" alt="等待处理"></p><ul><li><strong>系统行为</strong>： <ul><li>预警状态更新为 <strong>“已复核”</strong></li><li>不生成行动项</li><li>保留在预警记录中，供后续跟踪</li></ul></li></ul><h4 id="处理方式二-补充信息关闭" tabindex="-1">处理方式二：补充信息关闭 <a class="header-anchor" href="#处理方式二-补充信息关闭" aria-label="Permalink to &quot;处理方式二：补充信息关闭&quot;">​</a></h4><ul><li><strong>适用场景</strong>：问题已解决、无需进一步动作，或属于可接受偏差</li><li><strong>操作步骤</strong>： <ul><li>选择 <strong>“是”</strong></li><li>从下拉菜单选择 <strong>“补充信息关闭”</strong></li><li>填写补充说明</li><li>可上传附件作为证据</li></ul></li><li><strong>系统行为</strong>： <ul><li>预警状态变更为 <strong>“已关闭”</strong></li><li>不创建行动项</li><li>计入“有效预警-已闭环”统计，用于质量分析</li></ul></li></ul><p><img src="'+h+'" alt="补充信息关闭弹窗"></p><h4 id="处理方式三-添加行动项" tabindex="-1">处理方式三：添加行动项 <a class="header-anchor" href="#处理方式三-添加行动项" aria-label="Permalink to &quot;处理方式三：添加行动项&quot;">​</a></h4><ul><li><strong>适用场景</strong>：需明确责任人、整改措施和完成时限（如补签、数据修正、流程培训等）</li><li><strong>操作步骤</strong>： <ul><li>选择 <strong>“是”</strong></li><li>从下拉菜单选择 <strong>“添加行动项”</strong></li><li>填写措施、责任人、预计完成时间</li><li>可上传附件（如沟通记录、标准模板）</li></ul></li><li><strong>系统行为</strong>： <ul><li>自动生成一条 <strong>【待闭环行动项】</strong></li><li>自动分配至当前用户（或可指定其他责任人）</li><li>推送通知至责任人首页</li><li>行动项状态独立跟踪，支持上传整改证据与审核闭环</li></ul></li></ul><p><img src="'+g+'" alt="添加行动项弹窗"></p><blockquote><p>📌 <strong>注意事项</strong>：</p><ul><li>“附件”支持多文件上传（JPG、PNG、PDF、DOCX 等），单文件 ≤20MB</li><li>所有提交内容（包括处理方式、描述、附件）均永久留痕，支持审计追溯</li><li>一旦提交，处理方式不可更改；如需调整，请联系应用负责人发起修改流程</li></ul></blockquote><hr><h3 id="示例场景" tabindex="-1">示例场景 <a class="header-anchor" href="#示例场景" aria-label="Permalink to &quot;示例场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>实际场景</th><th>推荐处理方式</th><th>说明</th></tr></thead><tbody><tr><td>AI误判手写签名为“缺签”，实际已签署</td><td>补充信息关闭</td><td>上传说明，快速闭环</td></tr><tr><td>巡检表未填写设备编号，需补录</td><td>添加行动项</td><td>创建行动项任务，指派操作人</td></tr><tr><td>事故报告待法务审核后方可归档</td><td>等待处理</td><td>说明审核流程，暂缓处理</td></tr></tbody></table><blockquote><p>🔍 <strong>通用说明</strong>：<br> 上述三种处理方式适用于 <strong>图片类、文档类、APQP类</strong> 所有预警类型，确保问题响应路径灵活、合规、可追踪。</p></blockquote><h2 id="三、操作路径对照表" tabindex="-1">三、操作路径对照表 <a class="header-anchor" href="#三、操作路径对照表" aria-label="Permalink to &quot;三、操作路径对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>预警/行动项接收人</th><th>应用负责人</th></tr></thead><tbody><tr><td>复核预警</td><td>首页 →【待确认预警项】</td><td>应用中心 → 各子应用 → 查看预警项</td></tr><tr><td>闭环行动项</td><td>首页 →【待闭环行动项】</td><td>应用中心 → 各子应用 → 查看行动项</td></tr><tr><td>导出数据</td><td>❌ 不支持</td><td>✅ 支持（Excel、CSV）</td></tr><tr><td>全局检索</td><td>❌ 不支持</td><td>✅ 按片区/项目等条件筛选</td></tr></tbody></table><h2 id="四、常见问题-faq" tabindex="-1">四、常见问题（FAQ） <a class="header-anchor" href="#四、常见问题-faq" aria-label="Permalink to &quot;四、常见问题（FAQ）&quot;">​</a></h2><p><strong>Q：为什么我在首页看不到某条预警？</strong><br> A：该预警未分配给您。请确认所属工单/项目是否在您的责任范围内。</p><p><strong>Q：应用负责人能否代替接收人复核？</strong><br> A：不建议。系统遵循“谁接收、谁复核”原则，确保责任到人。</p><p><strong>Q：如何申请应用中心权限？</strong><br> A：联系系统管理员，提供角色证明。</p><blockquote><p>🔍 <strong>更多问题</strong>：参见 <a href="/oe-user-guide/faq">FAQ 文档</a></p></blockquote>',46)])])}const k=r(u,[["render",c]]);export{P as __pageData,k as default};
